import{at as e,n as t,rt as n,yt as r}from"./chunks/framework.ne95vkW4.js";var i=JSON.parse(`{"title":"emgr","description":"","frontmatter":{"title":"emgr","layout":"home","hero":{"name":"emgr","text":"Image resizing, in pure Rust","tagline":"An imgproxy-compatible service that fetches, resizes and caches images behind signed URLs. No C or C++ dependencies.","image":{"src":"/logo.svg","alt":"emgr"},"actions":[{"theme":"brand","text":"Get started","link":"/getting-started/installation"},{"theme":"alt","text":"API reference","link":"/user-guide/api-reference"},{"theme":"alt","text":"GitHub","link":"https://github.com/vaam-apps/image-resizer"}]},"features":[{"icon":"🔏","title":"Signed URLs, on by default","details":"HMAC-signed, imgproxy-compatible URLs, an SSRF-guarded fetcher, and a service that fails closed at startup until signing is configured.","link":"/user-guide/api-reference","linkText":"URL grammar"},{"icon":"🦀","title":"Pure-Rust codecs","details":"JPEG, PNG, WebP, AVIF and animated GIF/WebP through a SIMD resampler, with no C or C++ dependencies to build or patch.","link":"/architecture/components","linkText":"How it is built"},{"icon":"🗄️","title":"Pluggable storage","details":"Local filesystem, S3/MinIO or in-memory, chosen at compile time with Cargo features.","link":"/getting-started/installation","linkText":"Pick a backend"},{"icon":"☸️","title":"Ships to Kubernetes","details":"A Helm chart, a Knative Service chart for serverless setups, and Docker images for each storage flavour.","link":"/deployment/helm-chart","linkText":"Deploy it"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1792561504000}`),a={name:`index.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h2 id="welcome" tabindex="-1">Welcome <a class="header-anchor" href="#welcome" aria-label="Permalink to “Welcome”">​</a></h2><p>Welcome to the documentation for <strong>EmgR</strong>, a high-performance, imgproxy-compatible image resizing service built in Rust. It fetches a source image over HTTP(S), resizes/transforms it according to a signed URL, caches the result, and redirects the caller to it.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to “Features”">​</a></h2><ul><li>On-the-fly resizing via an <a href="./user-guide/api-reference">imgproxy-compatible signed URL scheme</a> - resize/crop, gravity, quality, blur, grayscale, watermarks and named presets.</li><li>JPEG, PNG, WebP (lossy and lossless), AVIF and animated GIF/WebP output, through a SIMD resampler (<code>fast_image_resize</code>) and a pure-Rust JPEG decode/encode path (<code>jpeg-decoder</code>/<code>jpeg-encoder</code>; DCT-scaled decode, progressive/subsampling control). Every image codec this service links — JPEG, WebP, AVIF — is pure Rust; there are no C or C++ dependencies.</li><li>Pluggable storage backends selected at <strong>compile time</strong> via Cargo feature flags: local filesystem, S3/MinIO, or in-memory (test builds only).</li><li>HMAC-signed URLs <strong>on by default</strong>, an SSRF-guarded source fetcher, and configurable resolution/output limits.</li><li>OpenTelemetry tracing and a bearer-token-protected <code>/metrics</code> endpoint, available behind the <code>otel</code> feature.</li><li>Kubernetes deployment via a Helm chart (or a Knative Service chart for serverless setups).</li></ul><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to “Before you start”">​</a></h2><p>Two things surprise newcomers, and both are deliberate:</p><ol><li><strong><code>emgr</code> has no default storage backend.</strong> <code>Cargo.toml</code> sets <code>default = []</code>, so a plain <code>cargo build</code> compiles but the resulting binary refuses to start (&quot;No storage features are enabled&quot;). Every build must name at least one of <code>local_fs</code>, <code>s3</code>, or <code>in_memory</code> explicitly.</li><li><strong>The service fails closed at startup</strong> unless signed URLs are configured (<code>SIGNING_KEY</code> + <code>SIGNING_SALT</code>) or you explicitly opt out with <code>ALLOW_UNSIGNED_REQUESTS=true</code>. A build with the <code>otel</code> feature adds a second, independent check for <code>/metrics</code>.</li></ol><p>See <a href="./getting-started/installation">Getting Started → Installation</a> for the full explanation, the exact commands, and every feature combination CI tests.</p><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to “Quick start”">​</a></h2><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/vaam-store/image-resizer.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> image-resizer</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># local_fs storage, signing turned off for local dev only - see</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Installation for the signed-URL alternative. --bin is required because</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># the crate also ships \`healthcheck\` and \`benchmark\` binaries.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LOCAL_FS_STORAGE_PATH</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">./data/images</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ALLOW_UNSIGNED_REQUESTS</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-default-features</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> local_fs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> emgr</span></span></code></pre></div><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:3000/health</span></span></code></pre></div><h2 id="api-overview" tabindex="-1">API overview <a class="header-anchor" href="#api-overview" aria-label="Permalink to “API overview”">​</a></h2><p>The service exposes a RESTful, imgproxy-compatible resize endpoint plus a download endpoint for already-cached results. See the <a href="./user-guide/api-reference">API Reference</a> for the full URL grammar, status codes and processing options, and <a href="./user-guide/examples">Examples</a> for computing a valid signature in Python/JavaScript/bash.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h2><p>The service is a hand-written Axum router (no OpenAPI code generation) over a small set of modular Rust services. See the <a href="./architecture/overview">architecture overview</a> and <a href="./architecture/components">components</a> pages.</p><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to “Deployment”">​</a></h2><p>Run it with <a href="./deployment/docker">Docker</a>, or deploy it to Kubernetes with the <a href="./deployment/helm-chart">Helm chart</a>.</p>`,17)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};